<?php
declare(strict_types=1);

namespace LifeOS;

/**
 * Join-page usernames are generated by the server and cannot be chosen by the member.
 * The form shows a signed preview; registration keeps that name only if the signature is valid
 * and the name is still free, otherwise it assigns a fresh generated name.
 */
final class Username
{
    public const PATTERN = '/^lifeos\d{6}$/';
    private const TTL = 7200;

    public static function taken(string $name): bool
    {
        return (bool) DB::one('SELECT id FROM users WHERE username = ? OR life_id = ? OR referral_code = ? OR phone = ? LIMIT 1', [$name, $name, $name, $name]);
    }

    public static function generate(): string
    {
        for ($i = 0; $i < 50; $i++) {
            $name = 'lifeos' . str_pad((string) random_int(0, 999999), 6, '0', STR_PAD_LEFT);
            if (!self::taken($name)) return $name;
        }
        throw new HttpError('Unable to generate a username, please try again', 503);
    }

    /** @return array{username: string, username_token: string} */
    public static function preview(): array
    {
        $name = self::generate();
        $exp = time() + self::TTL;
        return ['username' => $name, 'username_token' => $exp . '.' . self::sign($name, $exp)];
    }

    /** Returns the previewed name when the token is genuine, unexpired and the name is still free; null otherwise. */
    public static function fromToken(string $name, string $token): ?string
    {
        if (!preg_match(self::PATTERN, $name) || !preg_match('/^(\d{10})\.([a-f0-9]{64})$/', $token, $m)) return null;
        if ((int) $m[1] < time() || !hash_equals(self::sign($name, (int) $m[1]), $m[2])) return null;
        return self::taken($name) ? null : $name;
    }

    private static function sign(string $name, int $exp): string
    {
        return hash_hmac('sha256', 'username|' . $name . '|' . $exp, (string) Config::get('app_secret'));
    }
}
